import{_ as e,o as a,c as d,a5 as s}from"./chunks/framework.CslsFoWx.js";const h=JSON.parse('{"title":"Profils de magasin et appareils","description":"","frontmatter":{},"headers":[],"relativePath":"produit/profils.md","filePath":"produit/profils.md","lastUpdated":1793427717000}'),r={name:"produit/profils.md"};function i(o,t,n,p,l,c){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="profils-de-magasin-et-appareils" tabindex="-1">Profils de magasin et appareils <a class="header-anchor" href="#profils-de-magasin-et-appareils" aria-label="Permalink to &quot;Profils de magasin et appareils&quot;">​</a></h1><h2 id="profils-de-magasin" tabindex="-1">Profils de magasin <a class="header-anchor" href="#profils-de-magasin" aria-label="Permalink to &quot;Profils de magasin&quot;">​</a></h2><p>Le commerçant choisit son type de commerce à la création du magasin : cela active les bons modules et pré-configure l&#39;interface. Le cœur ne connaît pas les modules ; il expose des points d&#39;extension (ligne de panier, fiche produit, flux d&#39;encaissement, routage de commande).</p><table tabindex="0"><thead><tr><th>Module</th><th>Profils</th><th>Apporte</th><th>État</th></tr></thead><tbody><tr><td><code>tables</code></td><td>restaurant, café</td><td>plan de salle, additions ouvertes, partage</td><td><span class="badge ok">Fait</span> phase 2</td></tr><tr><td><code>kitchen</code></td><td>restaurant, café</td><td>postes de préparation, bons cuisine, écran cuisine (KDS)</td><td><span class="badge ok">Fait</span> phase 2</td></tr><tr><td><code>kiosk</code></td><td>restaurant, café, autres</td><td>self-service verrouillé</td><td><span class="badge partial">Partiel</span> presets configurés, app phase 4</td></tr><tr><td><code>variants</code></td><td>vêtements</td><td>matrice taille × couleur</td><td><span class="badge todo">À faire</span> phase 4</td></tr><tr><td><code>weight</code></td><td>épicerie</td><td>vente au poids, balance</td><td><span class="badge todo">À faire</span> phase 4</td></tr><tr><td><code>expiry</code></td><td>épicerie, pharmacie</td><td>dates de péremption, lots</td><td><span class="badge todo">À faire</span> phase 4</td></tr><tr><td><code>appointments</code></td><td>services</td><td>rendez-vous, prestations sans stock</td><td><span class="badge todo">À faire</span> phase 4</td></tr><tr><td><code>customer-credit</code></td><td>tous</td><td>ardoise (« karna »)</td><td><span class="badge todo">À faire</span> phase 3</td></tr><tr><td><code>loyalty</code></td><td>tous</td><td>points de fidélité</td><td><span class="badge todo">À faire</span> phase 3</td></tr></tbody></table><h2 id="les-appareils-d-un-magasin" tabindex="-1">Les appareils d&#39;un magasin <a class="header-anchor" href="#les-appareils-d-un-magasin" aria-label="Permalink to &quot;Les appareils d&#39;un magasin&quot;">​</a></h2><p>Le système n&#39;est pas « une caisse » mais une <strong>constellation d&#39;appareils</strong> rattachés au même magasin, chacun avec un <strong>rôle</strong> et des permissions (un kiosque ne fait pas de retour, un téléphone de salle n&#39;ouvre pas le tiroir).</p><table tabindex="0"><thead><tr><th>Rôle d&#39;appareil</th><th>Matériel</th><th>Ce qu&#39;il fait</th><th>Application</th></tr></thead><tbody><tr><td><code>REGISTER</code> — caisse</td><td>Tablette ou téléphone + douchette + imprimante + tiroir</td><td>Vente, encaissement, sessions, X/Z, retours, additions</td><td>Android, iOS</td></tr><tr><td><code>WAITER_TERMINAL</code> — téléphone de salle</td><td>Téléphone</td><td>Plan de salle, prise de commande, envoi cuisine, encaissement à la table selon la politique du magasin</td><td>Android, iOS</td></tr><tr><td><code>KDS</code> — écran cuisine</td><td>Tablette en cuisine</td><td>Bons par poste, états reçu → en préparation → prêt, délais</td><td>Android, iOS</td></tr><tr><td><code>KIOSK</code> — borne</td><td>Tablette verrouillée</td><td>Commande et paiement par le client</td><td>Phase 4 (presets déjà configurables)</td></tr><tr><td><code>BACKOFFICE</code> — web</td><td>Navigateur</td><td>Catalogue, équipe, apparence, rapports, supervision</td><td>Angular</td></tr></tbody></table><p>L&#39;appairage se fait par <strong>code court</strong> généré au back-office ; l&#39;appareil reçoit un jeton propre, génère son <strong>identité Ed25519</strong> et reçoit la clé LAN du magasin. Voir <a href="/VendoraSystem-docs/architecture/securite">sécurité</a>.</p>',8)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
